bl_info = {    "name": "Bake Helper: High → Low",    "author": "Custom",    "version": (1, 0, 0),    "blender": (5, 0, 0),    "location": "View3D > Sidebar > Bake | Object menu",    "description": "Запекание текстур с high-poly на low-poly с автопроверками",    "category": "Object",}import bpyfrom bpy.props import StringProperty, IntProperty, EnumProperty, FloatProperty, BoolProperty# ============================================================# 1. ХРАНИЛИЩЕ НАСТРОЕК# ============================================================class BAKOT_PG_settings(bpy.types.PropertyGroup):    high_name: StringProperty(name="High-poly объект")    low_name:  StringProperty(name="Low-poly объект")    bake_type: EnumProperty(        name="Тип карты",        items=[            ('DIFFUSE',     "Base Color (Diffuse)", "Цвет материала high-poly"),            ('NORMAL',      "Normal",      "Карта нормалей"),            ('AO',          "AO",          "Ambient Occlusion"),            ('ROUGHNESS',   "Roughness",   "Шероховатость"),            ('METALLIC',    "Metallic",    "Металличность"),            ('EMIT',        "Emission",    "Emission"),            ('DISPLACEMENT',"Displacement","Карта высот"),        ],        default='DIFFUSE',    )    resolution: IntProperty(name="Разрешение", default=2048, min=64, max=8192)    cage_extrusion: FloatProperty(name="Cage Extrusion", default=0.5, min=0.0, max=100.0)    margin: IntProperty(name="Margin (px)", default=4, min=0, max=64)    margin_type: EnumProperty(        name="Margin Type",        items=[            ('ADJACENT_FACES', "Adjacent Faces",             "Пиксели с соседних граней через UV-швы (меньше кровотечения)"),            ('EXTEND', "Extend",             "Растягивать крайние пиксели наружу (старый метод)"),        ],        default='ADJACENT_FACES',    )    samples: IntProperty(name="Samples", default=8, min=1, max=1024)    save_to_disk: BoolProperty(name="Сохранить PNG на диск", default=True)    auto_fix_selection: BoolProperty(name="Автоисправление выделения", default=True)    auto_zero_metallic: BoolProperty(        name="Автоматически обнулить Metallic",        description="Временно ставит Metallic=0 у материалов high-poly (причина №1 чёрной текстуры)",        default=True,    )    auto_boost_cage: BoolProperty(        name="Авто-подбор Cage Extrusion",        description="Если cage=0 или слишком мал — увеличивает до безопасного значения",        default=True,    )    auto_fix_normals: BoolProperty(        name="Пересчитать нормали",        description="Принудительно пересчитывает нормали наружу на high и low",        default=True,    )    run_preflight: BoolProperty(        name="Показать отчёт предпроверки перед запуском",        description="Если включено — после проверки откроется окно с найденными проблемами",        default=True,    )# ============================================================# 2. ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ# ============================================================def _unhide_object_recursive(obj):    obj.hide_viewport = False    obj.hide_set(False)    obj.hide_select = False    for coll in obj.users_collection:        coll.hide_viewport = False        coll.hide_select = False    def walk_layer(layer_coll):        for child in layer_coll.children:            if obj.name in child.collection.objects:                child.exclude = False                child.hide_viewport = False            walk_layer(child)    walk_layer(bpy.context.view_layer.layer_collection)def force_select(high_obj, low_obj, context):    vl = context.view_layer    for o in (high_obj, low_obj):        _unhide_object_recursive(o)        if o.name not in vl.objects:            try:                vl.link(o)            except Exception:                pass    for o in vl.objects:        o.select_set(False)    vl.objects.active = None    vl.update()    high_obj.select_set(True)    low_obj.select_set(True)    vl.objects.active = low_obj    selected = [o.name for o in context.selected_objects]    active = vl.objects.active.name if vl.objects.active else None    print(f"[BAKE] Выделено: {selected}  |  Активный: {active}")    if high_obj.name not in selected:        raise RuntimeError(f"Не удалось выделить high-poly '{high_obj.name}'")    if low_obj.name not in selected:        raise RuntimeError(f"Не удалось выделить low-poly '{low_obj.name}'")    if active != low_obj.name:        raise RuntimeError(f"Активным стал не low-poly, а '{active}'")    return high_obj, low_objdef _find_object(name, expected_role):    obj = bpy.data.objects.get(name)    if obj is None:        for o in bpy.data.objects:            if o.name.lower() == name.lower().strip():                print(f"[BAKE] Точное имя не найдено, использую '{o.name}' вместо '{name}'")                return o        raise ValueError(f"{expected_role} объект '{name}' не найден в файле")    return obj# ============================================================# 3. ПРЕДПОЛЁТНАЯ ДИАГНОСТИКА# ============================================================def _get_principled_bsdf(mat):    if not mat or not mat.use_nodes:        return None    for node in mat.node_tree.nodes:        if node.type == 'BSDF_PRINCIPLED':            return node    return Nonedef _get_socket(node, *names):    for n in names:        if n in node.inputs:            return node.inputs[n]    return Nonedef preflight_check(high_obj, low_obj, s, context):    warnings = []    fixes = []    undo = []    if not low_obj.data.uv_layers:        warnings.append("❌ LOW-POLY: нет UV-развёртки. Запекание невозможно.")        return warnings, fixes, undo    if low_obj.data.uv_layers.active is None:        warnings.append("⚠️ LOW-POLY: нет активного UV-слоя (UV Map).")    if not high_obj.data.materials:        warnings.append("❌ HIGH-POLY: нет материалов. Diffuse запечётся чёрным.")    else:        for i, mat in enumerate(high_obj.data.materials):            if mat is None:                warnings.append(f"⚠️ HIGH-POLY: пустой слот материала #{i}.")                continue            bsdf = _get_principled_bsdf(mat)            if bsdf is None:                warnings.append(                    f"⚠️ HIGH-POLY: материал '{mat.name}' без Principled BSDF — "                    f"Diffuse может запечься чёрным."                )                continue            metallic_sock = _get_socket(bsdf, "Metallic")            if metallic_sock is not None:                if not metallic_sock.is_linked:                    if metallic_sock.default_value > 0.5:                        msg = (                            f"❌ HIGH-POLY: материал '{mat.name}': "                            f"Metallic = {metallic_sock.default_value:.2f} → "                            f"Diffuse запечётся ЧЁРНЫМ."                        )                        if s.auto_zero_metallic:                            old = metallic_sock.default_value                            metallic_sock.default_value = 0.0                            fixes.append(f"✔ Metallic '{mat.name}': {old:.2f} → 0.0")                            undo.append(                                lambda sock=metallic_sock, val=old:                                    setattr(sock, "default_value", val)                            )                        else:                            warnings.append(msg)                else:                    warnings.append(                        f"⚠️ HIGH-POLY: материал '{mat.name}': Metallic подключён "                        f"к узлу — если значение 1.0, Diffuse будет чёрным."                    )            base_sock = _get_socket(bsdf, "Base Color")            if base_sock is not None and not base_sock.is_linked:                v = base_sock.default_value                if v[0] < 0.02 and v[1] < 0.02 and v[2] < 0.02:                    warnings.append(                        f"❌ HIGH-POLY: материал '{mat.name}': "                        f"Base Color = чёрный (0,0,0) → результат будет чёрным."                    )            alpha_sock = _get_socket(bsdf, "Alpha")            if alpha_sock is not None and not alpha_sock.is_linked:                if alpha_sock.default_value < 0.01:                    warnings.append(                        f"⚠️ HIGH-POLY: материал '{mat.name}': Alpha = 0 — "                        f"объект может быть невидим для лучей."                    )    try:        import mathutils        h_bb = [high_obj.matrix_world @ mathutils.Vector(c) for c in high_obj.bound_box]        l_bb = [low_obj.matrix_world @ mathutils.Vector(c) for c in low_obj.bound_box]        h_min = [min(v[i] for v in h_bb) for i in range(3)]        h_max = [max(v[i] for v in h_bb) for i in range(3)]        l_min = [min(v[i] for v in l_bb) for i in range(3)]        l_max = [max(v[i] for v in l_bb) for i in range(3)]        overlap = all(            h_min[i] <= l_max[i] and l_min[i] <= h_max[i]            for i in range(3)        )        if not overlap:            warnings.append(                "❌ HIGH и LOW объекты НЕ ПЕРЕСЕКАЮТСЯ в пространстве. "                "Лучи не найдут high-poly → чёрная текстура."            )        size = max(h_max[i] - h_min[i] for i in range(3))        if size > 0 and s.cage_extrusion < size * 0.01:            msg = (                f"⚠️ Cage Extrusion = {s.cage_extrusion:.3f} слишком мал "                f"для объекта размером {size:.2f}."            )            if s.auto_boost_cage:                new_val = max(size * 0.05, 0.5)                old_val = s.cage_extrusion                s.cage_extrusion = new_val                fixes.append(f"✔ Cage Extrusion: {old_val:.3f} → {new_val:.3f}")                undo.append(                    lambda prop=s, val=old_val:                        setattr(prop, "cage_extrusion", val)                )            else:                warnings.append(msg)    except Exception as e:        warnings.append(f"⚠️ Не удалось проверить bounding box: {e}")    if s.cage_extrusion <= 0.0001:        msg = "❌ Cage Extrusion = 0. Луч не выйдет из low-poly."        if s.auto_boost_cage:            s.cage_extrusion = 0.5            fixes.append("✔ Cage Extrusion: 0 → 0.5")            undo.append(lambda prop=s: setattr(prop, "cage_extrusion", 0.0))        else:            warnings.append(msg)    if s.auto_fix_normals:        try:            import bmesh            for obj in (high_obj, low_obj):                if len(obj.data.polygons) == 0:                    warnings.append(f"❌ '{obj.name}' не содержит полигонов.")                    continue                bm = bmesh.new()                bm.from_mesh(obj.data)                bmesh.ops.recalc_face_normals(bm, faces=bm.faces)                bm.to_mesh(obj.data)                bm.free()                obj.data.update()                fixes.append(f"✔ Нормали '{obj.name}' пересчитаны наружу")        except Exception as e:            warnings.append(f"⚠️ Не удалось пересчитать нормали: {e}")    if s.bake_type == 'DIFFUSE':        if not high_obj.data.materials:            warnings.append("❌ HIGH-POLY без материала — Diffuse будет чёрным.")        else:            has_bsdf = any(                _get_principled_bsdf(m) for m in high_obj.data.materials if m            )            if not has_bsdf:                warnings.append(                    "❌ У HIGH-POLY нет ни одного Principled BSDF."                )    if s.margin > 8:        warnings.append(            f"⚠️ Margin = {s.margin}px может «наползать» на соседние UV-острова. "            f"Рекомендуется 2–4px при Margin Type = Adjacent Faces."        )    return warnings, fixes, undo# ============================================================# 4. ОКНО ОТЧЁТА ПРЕДПРОВЕРКИ# ============================================================class BAKOT_OT_preflight_report(bpy.types.Operator):    bl_idname = "bake_helper.preflight_report"    bl_label = "Отчёт предпроверки"    bl_description = "Показывает найденные проблемы и автоматические исправления"    warnings: StringProperty(default="")    fixes: StringProperty(default="")    def invoke(self, context, event):        return context.window_manager.invoke_props_dialog(self, width=560)    def draw(self, context):        layout = self.layout        if self.fixes:            box = layout.box()            box.label(text="Автоматически исправлено:", icon='CHECKMARK')            for line in self.fixes.split("\n"):                if line.strip():                    box.label(text=line)        if self.warnings:            box = layout.box()            box.label(text="Требует внимания:", icon='ERROR')            for line in self.warnings.split("\n"):                if line.strip():                    box.label(text=line)        else:            box = layout.box()            box.label(text="Проблем не найдено — можно запекать.", icon='CHECKMARK')    def execute(self, context):        return {'FINISHED'}# ============================================================# 5. ГЛАВНЫЙ ОПЕРАТОР# ============================================================class BAKOT_OT_bake_high_to_low(bpy.types.Operator):    bl_idname = "bake_helper.bake_high_to_low"    bl_label = "Запечь High → Low"    bl_description = "Запекает выбранную карту с high-poly объекта на low-poly"    @classmethod    def poll(cls, context):        return context.mode == 'OBJECT'    def execute(self, context):        s = context.scene.bake_helper        if not s.high_name or not s.low_name:            self.report({'ERROR'}, "Укажите оба объекта")            return {'CANCELLED'}        if s.high_name.strip() == s.low_name.strip():            self.report({'ERROR'}, "High и Low — это должны быть разные объекты")            return {'CANCELLED'}        try:            high = _find_object(s.high_name, "High-poly")            low  = _find_object(s.low_name,  "Low-poly")        except ValueError as e:            self.report({'ERROR'}, str(e))            return {'CANCELLED'}        if high.type != 'MESH' or low.type != 'MESH':            self.report({'ERROR'}, "Оба объекта должны быть мешами (MESH)")            return {'CANCELLED'}        warnings, fixes, undo_actions = preflight_check(high, low, s, context)        critical = [w for w in warnings if w.strip().startswith("❌")]        if critical:            self.report(                {'ERROR'},                f"Найдено критических проблем: {len(critical)}. Смотри отчёт."            )            for w in critical:                print(f"[PREFLIGHT] {w}")            if s.run_preflight:                bpy.ops.bake_helper.preflight_report(                    'INVOKE_DEFAULT',                    warnings="\n".join(warnings),                    fixes="\n".join(fixes),                )            return {'CANCELLED'}        if s.run_preflight and (warnings or fixes):            print("\n===== ОТЧЁТ ПРЕДПРОВЕРКИ =====")            for f in fixes:                print(f"[PREFLIGHT] {f}")            for w in warnings:                print(f"[PREFLIGHT] {w}")            print("================================\n")        try:            img = bake_texture(high, low, s, context)        except Exception as e:            import traceback            traceback.print_exc()            self.report({'ERROR'}, f"Ошибка: {e}")            for action in undo_actions:                try:                    action()                except Exception:                    pass            return {'CANCELLED'}        saved_path = ""        if s.save_to_disk:            try:                saved_path = save_baked_image(img, low.name, s.bake_type)            except Exception as e:                self.report({'WARNING'}, f"Запечено, но не сохранено: {e}")        for action in undo_actions:            try:                action()            except Exception:                pass        msg = f"Готово: {img.name}" + (f" → {saved_path}" if saved_path else "")        if fixes:            msg += f" | авто-исправлений: {len(fixes)}"        self.report({'INFO'}, msg)        return {'FINISHED'}# ============================================================# 6. ОПЕРАТОР «ВЗЯТЬ ИЗ ВЫДЕЛЕНИЯ»# ============================================================class BAKOT_OT_fill_from_selection(bpy.types.Operator):    bl_idname = "bake_helper.fill_from_selection"    bl_label = "Взять имена из выделения"    bl_description = "Подставляет имена из выделения: активный = Low, второй = High"    @classmethod    def poll(cls, context):        return len(context.selected_objects) >= 2    def execute(self, context):        s = context.scene.bake_helper        sel = context.selected_objects        active = context.view_layer.objects.active        low = active if active in sel else sel[0]        highs = [o for o in sel if o != low]        if len(highs) != 1:            self.report({'ERROR'}, "Выделите ровно 2 объекта")            return {'CANCELLED'}        s.low_name = low.name        s.high_name = highs[0].name        self.report({'INFO'}, f"High: {s.high_name}, Low: {s.low_name}")        return {'FINISHED'}# ============================================================# 7. ЛОГИКА ЗАПЕКАНИЯ# ============================================================def bake_texture(high_obj, low_obj, s, context):    scene = context.scene    scene.render.engine = 'CYCLES'    scene.cycles.device = 'CPU'    scene.cycles.samples = s.samples    img_name = f"{low_obj.name}_{s.bake_type}_Baked"    if img_name in bpy.data.images:        bpy.data.images.remove(bpy.data.images[img_name])    img = bpy.data.images.new(img_name, width=s.resolution, height=s.resolution)    if s.bake_type in {'NORMAL', 'AO', 'ROUGHNESS', 'METALLIC', 'DISPLACEMENT'}:        img.colorspace_settings.name = 'Non-Color'    else:        img.colorspace_settings.name = 'sRGB'    mat = bpy.data.materials.new(name=f"{low_obj.name}_BakeMat")    mat.use_nodes = True    nodes = mat.node_tree.nodes    tex_node = nodes.new('ShaderNodeTexImage')    tex_node.image = img    nodes.active = tex_node    tex_node.select = True    if low_obj.data.materials:        low_obj.data.materials[0] = mat    else:        low_obj.data.materials.append(mat)    if s.auto_fix_selection:        force_select(high_obj, low_obj, context)    else:        bpy.ops.object.select_all(action='DESELECT')        high_obj.select_set(True)        low_obj.select_set(True)        context.view_layer.objects.active = low_obj    bake_settings = scene.render.bake    bake_settings.use_selected_to_active = True    bake_settings.cage_extrusion = s.cage_extrusion    bake_settings.margin = s.margin    bake_settings.margin_type = s.margin_type    bake_settings.use_clear = True    bake_settings.use_cage = False    if s.bake_type == 'DIFFUSE':        bake_settings.use_pass_direct   = False        bake_settings.use_pass_indirect = False        bake_settings.use_pass_color    = True    elif s.bake_type == 'EMIT':        bake_settings.use_pass_direct   = False        bake_settings.use_pass_indirect = False        bake_settings.use_pass_color    = False    print(f"[BAKE] {s.bake_type}: {high_obj.name} → {low_obj.name} @ {s.resolution}px")    print(f"[BAKE] cage_extrusion={s.cage_extrusion}, "          f"margin={s.margin}px ({s.margin_type})")    result = bpy.ops.object.bake(        type=s.bake_type,        use_selected_to_active=True,        cage_extrusion=s.cage_extrusion,        margin=s.margin,    )    if result != {'FINISHED'}:        raise RuntimeError(f"bake вернул {result}")    _diagnose_color(img, s.bake_type)    return imgdef _diagnose_color(img, bake_type):    try:        px = list(img.pixels[:4096])        if not px:            return        r, g, b = px[0], px[1], px[2]        if max(px) < 0.001:            print("[BAKE] ⚠️ Текстура полностью чёрная.")            return        if (bake_type == 'DIFFUSE'                and abs(r - 0.5) < 0.02                and abs(g - 0.5) < 0.02                and b > 0.95):            print("[BAKE] ⚠️ Результат похож на карту нормалей (голубой).")    except Exception:        passdef save_baked_image(img, low_name, bake_type):    blend = bpy.data.filepath    if blend:        folder = blend.rsplit('/', 1)[0].rsplit('\\', 1)[0]    else:        folder = bpy.utils.user_resource('DOCUMENTS', create=True)    path = f"{folder}/{low_name}_{bake_type}_Baked.png"    img.filepath_raw = path    img.file_format = 'PNG'    img.save()    print(f"[BAKE] Сохранено: {path}")    return path# ============================================================# 8. ПАНЕЛЬ В N-САЙДБАРЕ# ============================================================class BAKOT_PT_panel(bpy.types.Panel):    bl_label = "Bake Helper"    bl_idname = "BAKOT_PT_panel"    bl_space_type = 'VIEW_3D'    bl_region_type = 'UI'    bl_category = "Bake"    def draw(self, context):        layout = self.layout        s = context.scene.bake_helper        # --- Объекты ---        box = layout.box()        box.label(text="Объекты:", icon='OBJECT_DATA')        row = box.row(align=True)        row.prop(s, "high_name", text="High")        row = box.row(align=True)        row.prop(s, "low_name", text="Low")        row = box.row(align=True)        row.operator("bake_helper.fill_from_selection",                     text="Взять из выделения", icon='RESTRICT_SELECT_OFF')        # --- Параметры ---        box = layout.box()        box.label(text="Параметры:", icon='RENDER_STILL')        box.prop(s, "bake_type")        box.prop(s, "resolution")        box.prop(s, "cage_extrusion")        col = box.column(align=True)        col.label(text="Отступы (Margin):")        col.prop(s, "margin")        col.prop(s, "margin_type")        box.prop(s, "samples")        # --- Автопроверки ---        box = layout.box()        box.label(text="Автопроверки:", icon='CHECKMARK')        col = box.column(align=True)        col.prop(s, "auto_fix_selection")        col.prop(s, "auto_zero_metallic")        col.prop(s, "auto_boost_cage")        col.prop(s, "auto_fix_normals")        col.prop(s, "run_preflight")        # --- Сохранение ---        layout.prop(s, "save_to_disk")        # --- Кнопка запуска ---        layout.separator()        row = layout.row()        row.scale_y = 1.5        row.operator("bake_helper.bake_high_to_low",                     text="ЗАПЕЧЬ", icon='RENDER_STILL')# ============================================================# 9. ПУНКТ В МЕНЮ OBJECT# ============================================================def BAKOT_menu_object(self, context):    self.layout.separator()    self.layout.operator("bake_helper.bake_high_to_low",                         text="Запечь High → Low (Bake Helper)",                         icon='RENDER_STILL')# ============================================================# 10. РЕГИСТРАЦИЯ# ============================================================classes = (    BAKOT_PG_settings,    BAKOT_OT_preflight_report,    BAKOT_OT_bake_high_to_low,    BAKOT_OT_fill_from_selection,    BAKOT_PT_panel,)def register():    for c in classes:        bpy.utils.register_class(c)    bpy.types.Scene.bake_helper = bpy.props.PointerProperty(type=BAKOT_PG_settings)    bpy.types.VIEW3D_MT_object.append(BAKOT_menu_object)def unregister():    bpy.types.VIEW3D_MT_object.remove(BAKOT_menu_object)    if hasattr(bpy.types.Scene, "bake_helper"):        del bpy.types.Scene.bake_helper    for c in reversed(classes):        try:            bpy.utils.unregister_class(c)        except Exception:            passif __name__ == "__main__":    register()